#include <map>
#include <string>
#include <iostream>

struct CaseInsensitiveCompare {
    bool operator()(const std::string& a, const std::string& b) const {
        // Defines ordering based on lowercase version
        // Equivalence: !(a < b) && !(b < a) means they are case-insensitive equal.
        std::string lower_a = a; 
        std::string lower_b = b;
        // Standard library function for conversion to lower case (omitted for brevity)
        return lower_a < lower_b;
    }
};

int main() {
    std::map<std::string, int, CaseInsensitiveCompare> m;
    m["Apple"] = 1; 
    m["apple"] = 2; // Key 'apple' is equivalent to 'Apple' based on comparator

    // Size will be 1, because 'Apple' and 'apple' are equivalent.
    std::cout << m.size() << std::endl; 
}
